style.css:
@-moz-document domain("kkutu.co.kr") {
/* 전체 배경/글자 색상 */
  body, html {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* 헤더, 네비게이션 바 */
  header, nav, .navbar, .header, .nav {
    background-color: #1f1f1f !important;
    border-bottom: 1px solid #333 !important;
  }

  /* 링크, 버튼 */
  a, a:link, a:visited {
    color: #80cbc4 !important;
  }
  a:hover, a:focus {
    color: #b2dfdb !important;
  }
  button, input[type="button"], input[type="submit"], .btn {
    background-color: #272727 !important;
    color: #e0e0e0 !important;
    border: 1px solid #444 !important;
  }

  /* 콘텐츠 영역 배경 */
  .content, .main, .wrapper, .container {
    background-color: #181818 !important;
  }

  /* 카드, 박스 스타일 */
  .card, .box, .panel {
    background-color: #1e1e1e !important;
    border: 1px solid #333 !important;
  }

  /* 입력창, 텍스트 영역 */
  input, textarea, select {
    background-color: #262626 !important;
    color: #e0e0e0 !important;
    border: 1px solid #444 !important;
  }

  /* 테이블, 목록 등 */
  table, thead, tbody, th, td {
    background-color: transparent !important;
    color: #e0e0e0 !important;
    border-color: #333 !important;
  }

  /* 밝은 이미지를 강제로 어둡게 하지 않기 (필요하면 조절) */
  img, video {
    filter: none !important;
  }

  /* 광고, 배너 숨김 (클래스명 조정 필요할 수 있음) */
  [class*="ad"], [id*="ad"], .banner, .advertisement {
    display: none !important;
  }

  /* 포커스나 강조 색상 */
  :focus, :hover {
    outline: 1px solid #80cbc4 !important;
  }
}
